src/screens/auth/RegisterSuccessScreen.t.fix:
Capture and clear the timer, and abort if unmounted:

useEffect(() => {
  let timer: ReturnType<typeof setTimeout> | undefined;
  let cancelled = false;
  Animated.sequence([ ... ]).start();
  const doRefreshAndContinue = async () => {
    try { await refreshUser(); } catch (e) {}
    if (cancelled) return;
    timer = setTimeout(() => { handleContinue(); }, 2000);
  };
  doRefreshAndContinue();
  return () => { cancelled = true; if (timer) clearTimeout(timer); };
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, []);

Guard with a ref so it only navigates once:

const hasNavigated = useRef(false);
const handleContinue = () => {
  if (hasNavigated.current) return;
  hasNavigated.current = true;
  navigation.reset({ index: 0, routes: [{ name: 'Main' as any }] });
};

