src/screens/profile/PaymentMethodsScreen.fix:
Clear the state on every path that lacks data:

const loadExchangerInfo = useCallback(async () => {
  if (!user?.uid) {
    setSavedExchangerInfo(null);   // clear on logout / no user
    setExchangerLoading(false);
    return;
  }
  try {
    const { data } = await supabase.from('users').select('money_exchanger_info').eq('id', user.uid).single();
    if (data?.money_exchanger_info) {
      setSavedExchangerInfo(data.money_exchanger_info as SavedMoneyExchangerInfo);
    } else {
      setSavedExchangerInfo(null); // clear when this user has none
    }
  } catch { /* ignore */ } finally {
    setExchangerLoading(false);
  }
}, [user?.uid]);
